content.text:
The incident has one fault that reaches users: the search→geo connection is delayed, and that propagates up to the frontend. Writing up the findings.

```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) AS n, approx_quantile(p.duration,0.5)/1e6 AS caller_ms_p50, approx_quantile(c.duration,0.5)/1e6 AS callee_ms_p50, approx_quantile(extract(epoch FROM c.time)-extract(epoch FROM p.time),0.5)*1000 AS start_gap_ms_p50, approx_quantile((extract(epoch FROM p.time)+p.duration/1e9)-(extract(epoch FROM c.time)+c.duration/1e9),0.5)*1000 AS end_gap_ms_p50 FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='search' AND c.service_name='geo' GROUP BY 1,2",
          "claim": "search's geo.Geo/Nearby calls take about 1.6 s before geo starts; geo's own span is about 0.1 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY 1,2 UNION ALL SELECT service_name, span_name, count(*), approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY 1,2",
          "claim": "Geo's own server span p95 stays about 0.2 ms in both periods; the delay is outside geo's processing."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('geo.Geo/Nearby','rate.Rate/GetRates') GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE service_name='search' AND span_name IN ('geo.Geo/Nearby','rate.Rate/GetRates') GROUP BY 1,2",
          "claim": "search's geo call p95 rose from 0.6 ms to about 2,944 ms while its rate call stayed about 8 ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms, min(duration)/1e6 min_ms FROM abnormal_traces WHERE service_name='search' AND span_name='search.Search/Nearby' GROUP BY 1,2",
          "claim": "search.Search/Nearby p95 rose to about 2,949 ms, with minimum 1,435 ms, matching the geo call wait."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2",
          "claim": "Frontend HTTP /hotels p95 rose to about 2,956 ms, tracking search's Nearby latency; frontend's own time stays about 2.6 ms."
        }
      ]
    }
  ]
}
```

